fn is_ascii_digit(c: char) -> bool {
    c >= '0' && c <= '9'
}

fn all_digits(s: String) -> bool {
    // Invariant: at the start of each loop iteration,
    // `all_good` logically holds whether all characters seen so far are ASCII digits.
    for c in s.chars() {
        if !is_ascii_digit(c) {
            return false;
        }
    }
    true
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_is_ascii_digit() {
        for c in '0'..='9' {
            assert!(is_ascii_digit(c));
        }
        // Test some non-digits
        assert!(!is_ascii_digit('a'));
        assert!(!is_ascii_digit(' '));
        assert!(!is_ascii_digit('-'));
        assert!(!is_ascii_digit('０')); // Full-width '0'
    }

    #[test]
    fn test_all_digits() {
        assert!(all_digits(String::new()));          // empty string
        assert!(all_digits("0123456789".to_string()));
        assert!(!all_digits("123a45".to_string()));
        assert!(!all_digits(" 12345".to_string()));
        assert!(!all_digits("１２３４５".to_string())); // full-width digits
    }
}